// Loop over input items and add a new field called 'myNewField' to the JSON of each one
for (const item of $input.all()) {

  let prompt_out = ``;
  let tabela_out = ``;
  let tabela_transacoes_gasto = `### Tabela de Transações de Gastos:
**Nome tabela:** tb_gastos_transacoes

**Colunas:**
- id (Gerado automaticamente pelo banco de dados)
- id_cliente bigint (Obrigatório) (Identificação do cliente);
- dt_gasto date (Obrigatório) (Data do gasto - formato: DD/MM/AAAA);
- descricao_gasto text (Obrigatório) (Descrição do gasto);
- valor text (Obrigatório) (Valor do gasto);
- categoria text (Obrigatório) (Categoria do gasto);

**Tipos de categoria para coluna categoria**
- Moradia: Aluguel, condomínio, IPTU, contas de água, luz, gás, reformas, etc.
- Alimentação: Supermercado, restaurantes, delivery, lanches, etc.
- Transporte: Carro (combustível, manutenção, seguro, estacionamento), transporte público, passagens aéreas, transportes por aplicativo, etc.
- Saúde: Planos de saúde, consultas médicas, medicamentos, tratamentos, etc.
- Educação: Mensalidades escolares, cursos, livros, materiais, etc.
- Lazer: Cinema, shows, viagens, restaurantes, hobbies, etc.
- Vestuário: Roupas, sapatos, acessórios, lavanderia, etc.
- Serviços: Internet, telefone, TV a cabo, streaming, academia, assinaturas, etc.
- Dívidas: Pagamento de empréstimos, cartões de crédito, financiamentos, etc. `;

  let tabela_meta_gasto = `### Tabela de Limites de Gastos:
**Nome tabela:** tb_gastos_limites

**Colunas:**
- id_cliente bigint (Obrigatório) (Identificação do cliente);
- periodo text (Obrigatório) (Valores possíveis: DIARIO, SEMANAL, MENSAL);
- valor_limite double precision (Obrigatório) (Valor limite do período);
- dt_inicio date (Obrigatório) (Data início da vigência);
- dt_fim date (Obrigatório) (Data fim da vigência);
- renova_automatico char(1) (Obrigatório) (Valores possíveis: S, N);
- dt_cadastro date (Obrigatório) (Data de criação do registro);
- dt_alteracao date (Opcional) (Data da última alteração);
- status text (Obrigatorio) (Valores possíveis: A, D); **A: Ativado - D: Desativado**
- porcentagem_alerta integer not null default 100`;

  let prompt_criar_gasto = `**Criar novo gasto:**
- Campos obrigatórios da tabela tb_gastos_transacoes: id_cliente, dt_gasto, descricao_gasto, valor e categoria.
- Utilize sempre o id_cliente fornecido na mensagem.
- Se o usuário informar somente o valor e a descricao_gasto, chame a tool "operacao_db_controle_gastos" imediatamente, e defina a dt_gasto e a categoria conforme as instruções do prompt.
- Se não informar a data (dt_gasto), assuma hoje como data padrão.
- Se não informar a categoria, defina a categoria que melhor se encaixa com a descrição do gasto.
- Para datas relativas como "hoje", "ontem", "agora", "acabei de gastar", converta para formato DD/MM/AAAA.
- Normalize o valor para text (ex.: "45,30").
- Normalize a descricao_gasto em formato padronizado (ex.: "Comprei um lanche na padaria" → "LANCHE NA PADARIA").
- Após coletar os dados necessários (valor, descricao_gasto e categoria), chame a tool acessar_banco com os dados completos e formatados em maiúsculo, conforme exemplo:
"Operação: Inserir novo registro na tabela tb_gastos_transacoes; id_cliente: XXX, dt_gasto: DD/MM/AAAA, descricao_gasto: XXX, valor: XXX, categoria: XXX".
- Assim que cadastrar com sucesso, informe ao usuário que o gasto foi registrado com sucesso e exiba uma prévia do que foi cadastrado no formato:
dt_gasto: DD/MM/AAAA
descricao_gasto: XXX
valor: R$ XXX,XX
categoria: XXX
- Obs.: Todos os textos devem ser salvos em letras maiúsculas.`;

  let prompt_consultar_gasto = `**Consultar gastos:**
- Consulte apenas dados do id_cliente fornecido na mensagem do usuário.
- Para a consulta, se o usuário não informar nenhum dado como dt_gasto, descricao_gasto, valor, categoria ou período, peça a ele que informe um filtro.
- Se ele informar que quer consultar todos os dados, faça a consulta de todos os gastos do usuário.
- Para realizar a consulta, chame a tool "operacao_db_controle_gastos", conforme exemplo:
"Operação: Consultar registro na tabela tb_gastos_transacoes; Filtro: id_cliente: XXX, dt_gasto: DD/MM/AAAA até DD/MM/AAAA categoria: XXX"
Retorne os resultados ao usuário no formato:
dt_gasto: DD/MM/AAAA
descricao_gasto: XXX
valor: R$ XXX,XX
categoria: XXX

- Não exiba ao usuário as colunas id e id_cliente.
- Se ocorrer um erro na consulta, informe ao usuário que não conseguiu encontrar o gasto dos dados que ele passou (Ex. "Não consegui encontrar gastos com a descrição ALIMENTAÇÃO na data informada, está correto?").`;

  let prompt_atualizar_gasto = `**Atualizar gasto:**
- Para atualizar algum gasto o usuário deverá passar dados para que seja possível localizar o gasto que deseja atualizar.
- Utilize os mesmos critérios de "Consultar gastos" para localizar o gasto.
- Assim que localizar o(s) gasto(s), exiba os gastos encontrados para o usuário, com todas as informações do gasto.
- Caso encontre mais de um gasto, liste os gastos encontrados e pergunte qual gasto deverá ser alterado, um especifico, mais de um ou todos.
- SEMPRE confirme com o usuário os dados que irá atualizar, mostrando uma prévia de como os dados ficarão após sua atualização.
- ATENÇÃO! Com a confirmação do usuário, chame OBRIGATORIAMENTE a tool "operacao_db_controle_gastos" para atualizar a informação do gasto passando os filtros para localizar e a instrução de atualização de forma literal, como o exemplo abaixo:
"Operação: Atualizar registro na tabela tb_gastos_transacoes; Atualizar o campo: valor para XXX; Filtro: id: XXXX id_cliente: XXX, dt_gasto: DD/MM/AAAA, descricao_gasto: XXX"
- Somente se o gasto for atualizado com sucesso no banco de dados chamando a tool "operacao_db_controle_gastos", informe ao usuário que o gasto foi atualizado, e exiba os dados do gasto atualizados, no formato abaixo:
dt_gasto: DD/MM/AAAA
descricao_gasto: XXX
valor: R$ XXX,XX
categoria: XXX`;

  let prompt_deletar_gasto = `**Deletar gasto:**
- Para excluir algum gasto o usuário deverá passar dados para que seja possível localizar o gasto que deseja excluir.
- Utilize os mesmos critérios de "Consultar gastos" para localizar o gasto.
- Assim que localizar o(s) gasto(s), exiba os gastos encontrados para o usuário, com todas as informações do gasto.
- Caso encontre mais de um gasto, liste os gastos encontrados e pergunte qual gasto deverá ser deletado, um especifico, mais de um ou todos.
- SEMPRE confirme com o usuário se ele realmente deseja excluir o gasto, mostrando os dados completos que serão removidos.
- ATENÇÃO! Com a confirmação do usuário, chame OBRIGATORIAMENTE a tool "operacao_db_controle_gastos" para excluir o gasto passando os filtros para localizar, conforme exemplo:
"Operação: Excluir registro na tabela tb_gastos_transacoes; Filtro: id: XXX id_cliente: XXX, dt_gasto: DD/MM/AAAA, descricao_gasto: XXX"
- Somente se o gasto for excluído com sucesso no banco de dados chamando a tool "operacao_db_controle_gastos", informe ao usuário que o gasto foi excluído com sucesso.
- Se ocorrer erro na exclusão, informe ao usuário e solicite que tente novamente.`;

  let prompt_meta_criar = `**Configurar limite de gasto:**
- Para configurar limites de gastos na tabela tb_gastos_limites, colete os dados obrigatórios: periodo (DIARIO, SEMANAL, MENSAL), valor_limite, dt_inicio, dt_fim, renova_automatico e porcentagem_alerta.
- Utilize sempre o id_cliente fornecido na mensagem.
- Para periodo DIARIO: calcule dt_fim como mesmo dia da dt_inicio.
- Para periodo SEMANAL: calcule dt_fim como 7 dias após dt_inicio.
- Para periodo MENSAL: calcule dt_fim como último dia do mês da dt_inicio.
- Defina dt_cadastro como a data atual.
- Para renovacao_automatico, pergunte apenas se o usuário quer ou não quer a renovação automática. Caso ele responda "SIM" assuma "S", caso responda "NAO" assuma "N".
- O campo renovacao_automatico indica que quando o limite expirar (Com base na dt_fim) será criado um novo parâmetro que com os mesmos dados, para o próximo periodo, explique isso para o cliente se necessário.
- Para coluna status, quando for criado um limite de gasto, o valor será "A".
- Para a coluna porcentagem_alerta, pergunte ao usuário se ele deseja ser avisado quando o valor gasto atingir uma determinada porcentagem do valor cadastrado como valor_limite.
- O valor da coluna porcentagem_alerta precisa ser inteiro (Ex. 70, para 70%).
- Se faltar informação, pergunte apenas pelo dado faltante, sem exibir prévia.
- Após coletar todos os dados obrigatórios, exiba uma prévia e solicite confirmação no formato:
"Esses foram os dados coletados, posso criar o limite de gastos?
periodo: XXX
valor_limite: R$ XXX,XX
dt_inicio: DD/MM/AAAA
dt_fim: DD/MM/AAAA
renova_automatico: X
porcentagem_alerta: XX"

- Se o usuário solicitar alterações, atualize os dados e reenvie a prévia até a confirmação.
- Após confirmação, chame a tool "operacao_db_controle_gastos" com os dados completos, conforme exemplo:
"Operação: Inserir novo registro na tabela tb_gastos_limites; id_cliente: XXX, periodo: MENSAL, valor_limite: 1500.00, dt_inicio: DD/MM/AAAA, dt_fim: DD/MM/AAAA, renova_automatico: S, dt_cadastro: DD/MM/AAAA status: A"`;

  let prompt_meta_consultar = `**Consultar limites/metas/alertas:**
- Consulte limites do id_cliente fornecido na mensagem na tabela tb_gastos_limites.
- Chame a tool "operacao_db_controle_gastos" somente com o id_cliente, conforme exemplo:
"Operação: Consultar registro na tabela tb_gastos_limites; Filtro: id_cliente: XXX"
- Apresente os limites no formato:
periodo: XXX
valor_limite: R$ XXX,XX
dt_inicio: DD/MM/AAAA
dt_fim: DD/MM/AAAA
renova_automatico: X
porcentagem_alerta: XX

- Não exiba id_cliente, dt_cadastro ou dt_alteracao.
- Se não houver limites cadastrados, informe e pergunte se deseja criar um novo limite.
- Consulte apenas limites ativos (status = 'A')
- Caso não tenha limite ativo, informe ao usuário que ele não possui nenhum limite ativo cadastrado`;

  let prompt_meta_atualizar = `### **Atualizar limite de gastos (OPERACAO_DE_BANCO-ATUALIZAR):**

- Para atualizar algum limite de gastos o usuário deverá passar dados para que seja possível localizar o registro que deseja atualizar.
- Utilize critérios como id_cliente, periodo, status ou datas de vigência para localizar o limite.
- Assim que localizar o(s) limite(s), exiba os registros encontrados para o usuário, com todas as informações do limite de gastos.
- Caso encontre mais de um registro, solicite ao usuário para informar o período específico que ele quer atualizar.
- **SEMPRE** confirme com o usuário os dados que irá atualizar, mostrando uma prévia de como os dados ficarão após sua atualização.
- **ATENÇÃO!** Com a confirmação do usuário, chame **OBRIGATORIAMENTE** a tool "operacao_db_controle_gastos" para atualizar a informação do limite passando o id_cliente e a instrução de atualização de forma literal, como o exemplo abaixo:

  "Operação: Atualizar registro; Atualizar o campo: valor_limite para XXX; Filtro: id_cliente: XXX e periodo: XXX"

- Sempre atualize o campo dt_alteracao com a data atual quando realizar qualquer alteração.
- Valide que periodo aceita apenas: DIARIO, SEMANAL ou MENSAL.
- Valide que renova_automatico aceita apenas: S ou N.
- Valide que status aceita apenas: A ou D.
- Valide que porcentagem_alerta deve ser um valor entre 0 e 100.
- Somente se o limite for atualizado com sucesso no banco de dados chamando a tool "operacao_db_controle_gastos", informe ao usuário que o limite foi atualizado, e exiba os dados do limite atualizados, no formato abaixo:


id_cliente: XXX
periodo: XXX
valor_limite: R$ XXX
dt_inicio: DD/MM/AAAA
dt_fim: DD/MM/AAAA
renova_automatico: XXX
status: XXX
porcentagem_alerta: XXX
dt_alteracao: DD/MM/AAAA`;

  let prompt_meta_deletar = `### **Deletar limite de gastos (OPERACAO_DE_BANCO-DELETAR):**

- Para deletar algum limite de gastos o usuário deverá passar dados para que seja possível localizar o registro que deseja deletar.
- Utilize critérios como id_cliente, periodo, status ou datas de vigência para localizar o limite.
- Assim que localizar o(s) limite(s), exiba os registros encontrados para o usuário, com todas as informações do limite de gastos.
- Caso encontre mais de um registro, solicite ao usuário para informar o ID do cliente e/ou período específico que ele quer deletar.
- **ATENÇÃO!** Delete o limite apenas com a confirmação do usuário.
- **ATENÇÃO!** Assim que tiver o registro que deverá ser deletado, chame a tool "operacao_db_controle_gastos" passando o id_cliente e período e a instrução de deleção de forma literal, como o exemplo abaixo:

  "Operação: Deletar registro; Filtro: id_cliente: XXX e periodo: XXX;"

- Se o registro for deletado com sucesso, informe ao usuário que o limite de gastos foi apagado.`;

  if ($input.first().json.output === "GASTO-CRIAR") {
    tabela_out = tabela_transacoes_gasto;
    prompt_out = prompt_criar_gasto;
  } 

  if ($input.first().json.output === "GASTO-CONSULTAR"){
    tabela_out = tabela_transacoes_gasto;
    prompt_out = prompt_consultar_gasto;
  } 

  if ($input.first().json.output === "GASTO-ATUALIZAR"){
    tabela_out = tabela_transacoes_gasto;
    prompt_out = prompt_atualizar_gasto || `

` || prompt_consultar_gasto;
  } 

  if ($input.first().json.output === "GASTO-DELETAR"){
    tabela_out = tabela_transacoes_gasto;
    prompt_out = prompt_deletar_gasto || `

` || prompt_consultar_gasto;
  } 

  if ($input.first().json.output === "META-CRIAR"){
    tabela_out = tabela_meta_gasto;
    prompt_out = prompt_meta_criar;
  } 

  if ($input.first().json.output === "META-CONSULTAR"){
    tabela_out = tabela_meta_gasto;
    prompt_out = prompt_meta_consultar;
  } 

  if ($input.first().json.output === "META-ATUALIZAR"){
    tabela_out = tabela_meta_gasto;
    prompt_out = prompt_meta_atualizar;
  } 

  if ($input.first().json.output === "META-DELETAR"){
    tabela_out = tabela_meta_gasto;
    prompt_out = prompt_meta_deletar;
  } 

  return {
      json: {
        prompt: prompt_out,
        tabela: tabela_out
      }
    };
}
